// Some portions generated by Claude
// Some portions generated by Codex
import test from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { importedStylesheets, inventory } from "../../../../scripts/css-inventory.mjs";

// The explorer's stylesheet is loaded into every Workbench page once the Graph page has been visited, so every rule
// must be scoped under .graph-explorer (or the html[data-theme] switch) and must not restyle the Workbench's own
// elements. Class names the TSX uses must be styled either here or by the Workbench design system (workbench-*).
const css = importedStylesheets().map(file => readFileSync(file, "utf8")).join("\n");

test("the inventory follows local stylesheet imports and checks each module's selectors", context => {
  const directory = mkdtempSync(join(tmpdir(), "rdf4j-css-inventory-"));
  context.after(() => rmSync(directory, { recursive: true, force: true }));
  mkdirSync(join(directory, "nested"));
  writeFileSync(join(directory, "app.tsx"), `
    import "./root.css";
    import styles from "./named.css";
    import("./lazy.css");
    export const app = <div className="root named lazy nested" />;
  `);
  writeFileSync(join(directory, "nested", "view.tsx"), 'import "./view.css";');
  writeFileSync(join(directory, "root.css"), ".graph-explorer .root { color: red; }");
  writeFileSync(join(directory, "named.css"), ".named { color: red; }");
  writeFileSync(join(directory, "lazy.css"), ".graph-explorer .lazy { color: red; }");
  writeFileSync(join(directory, "nested", "view.css"), ".graph-explorer .nested { color: red; }");
  writeFileSync(join(directory, "unused.css"), ".unused { color: red; }");
  assert.deepEqual(importedStylesheets(directory).map(file => relative(directory, file)),
    ["lazy.css", "named.css", "nested/view.css", "root.css"]);
  const result = inventory(directory);
  assert.deepEqual(result.missing, []);
  assert.deepEqual(result.unscoped, [".named"]);
  assert.equal(result.defined.has("unused"), false, "an unimported stylesheet cannot satisfy coverage");
});

test("every explorer selector is scoped under .graph-explorer", () => {
  const { unscoped } = inventory();
  assert.deepEqual(unscoped.slice(0, 10), [], `${unscoped.length} unscoped selectors`);
});

test("every class the explorer uses is styled by the explorer or by the Workbench design system", () => {
  const { missing } = inventory();
  assert.deepEqual(missing.filter((name) => !name.startsWith("workbench-")), []);
});

test("the explorer takes its colours, fonts and radii from the Workbench tokens", () => {
  assert.doesNotMatch(css, /@import/, "no Tailwind or web-font imports");
  assert.doesNotMatch(css, /fonts\.googleapis|Inter|IBM Plex/, "no web fonts");
  for (const token of ["--workbench-ink", "--workbench-surface", "--workbench-primary", "--workbench-font", "--workbench-code-font",
    "--workbench-radius", "--workbench-soft-rule"]) {
    assert.match(css, new RegExp(`var\\(${token}\\)`), token);
  }
  assert.match(css, /html\[data-theme="dark"\] \.graph-explorer/, "dark theme follows the Workbench switch");
  assert.doesNotMatch(css, /^\s*(\*|html|body|button|input|select|textarea|code)\s*(,|\{)/m, "no element-level rules");
});

test("edges and their arrowheads share one opaque colour", () => {
  // A translucent stroke under a translucent arrowhead doubles its alpha: the line shows through the head.
  const edge = /--graph-explorer-edge:\s*([^;]+);/.exec(css)?.[1] ?? "";
  assert.match(edge, /var\(--workbench-muted\)/, edge);
  assert.doesNotMatch(edge, /transparent/, `--graph-explorer-edge: ${edge}`);
});

test("an edge drawn in the accent colour gets an accent arrowhead", () => {
  // A marker takes its colour from where it is defined, not from the edge drawing it: without its own arrowhead an
  // emphasised (accent) line keeps the grey head of the plain edges.
  const app = readFileSync(fileURLToPath(new URL("../../../main/frontend/graph-explorer/GraphExplorerApp.tsx", import.meta.url)), "utf8");
  assert.match(app, /<marker id="arrow-accent"[^]*?fill: "var\(--accent\)"[^]*?<\/marker>/);
  const selectors = (block) => block.split(",").map((selector) => selector.trim().replace(/^\.graph-explorer /, ""));
  const rules = css.replace(/\/\*[^]*?\*\//g, "");
  const accentEdges = [...rules.matchAll(/([^{}]+)\{\s*color: var\(--accent\);\s*\}/g)]
    .flatMap(([, block]) => selectors(block)).filter((selector) => /\.edge[.:\s]|\.edge$/.test(selector));
  assert.ok(accentEdges.length >= 4, accentEdges.join(", "));
  const accentHeads = [...rules.matchAll(/([^{}]+)\{\s*marker-end: url\(#arrow-accent\);\s*\}/g)].flatMap(([, block]) => selectors(block));
  assert.deepEqual(accentEdges.filter((selector) => !accentHeads.includes(`${selector} path`)), []);
});
